def main():
    for m,i,t in [(54,14,'埃癸斯小姐\n无法战斗了……'),(56,9,'岳羽由加莉小姐的石像…\n在下给３颗星。'),(56,18,'啊……善和玲都成了石头……\n两个人都成了石头！'),(56,21,'如今的队长大人身上，\n透着坚如磐“石”的意志…'),(58,16,'虎狼丸大人竟在敌前熟睡……\n真是大胆。')]:
        TEXT[m][INDICES.index(i)]=t
    target=ROOT/'translation/batches/387_elizabeth_statuses.generated.json';assert not target.exists()
    rows=read(ROOT/'translation/catalog.working.json');sources=defaultdict(list);selected=0
    for member,values in TEXT.items():
        assert len(values)==20
        source=f'export_dlc/0006/battle/support/bsv121.bvp_({member:03}).BMD.json';doc=read(ROOT/source)
        for i,body in zip(INDICES,values):
            key=f'{source}:{i}:0';row=next(r for r in rows if r['key']==key);assert not row.get('translation')
            old=row['original'];body+='\n'
            assert not TOKEN.findall(body)
            a=TOKEN.sub('',old).splitlines();b=body.splitlines()
            assert len(b)<=len(a) and max(map(len,b))<=max(map(len,a)),(member,i)
            sources[source].append([i,0,doc['texts'][i]['id'],body]);selected+=1
    write(target,dict(status='draft',sources=dict(sources),source_hashes={s:hashlib.sha256((ROOT/s).read_bytes()).hexdigest() for s in sources},review_notes=['DLC0006伊丽莎白054—060，战斗不能/濒危/石化/中毒/睡眠/麻痹/诅咒。','石化可能是遗留状态台词，翻译不代表确认游戏会触发。每组5/13号dummy原样保留。','诅咒警告指主动攻击引发危险，不误译为受到攻击；人物双关尽量保留。']))
    print('Status pages:',selected)

if __name__=='__main__':main()
